import unittest

from solution import endpoint_plan


class EndpointPlanTests(unittest.TestCase):
    def test_ipv4_bind_and_public_address(self):
        self.assertEqual(endpoint_plan("192.0.2.10", 8080), {
            "bind": ("192.0.2.10", 8080),
            "advertised": "http://192.0.2.10:8080",
        })
        self.assertEqual(endpoint_plan("192.0.2.10", 443, "198.51.100.8"), {
            "bind": ("192.0.2.10", 443),
            "advertised": "http://198.51.100.8:443",
        })

    def test_ipv4_wildcard_advertises_loopback(self):
        self.assertEqual(endpoint_plan("0.0.0.0", 9000), {
            "bind": ("0.0.0.0", 9000),
            "advertised": "http://127.0.0.1:9000",
        })

    def test_ipv6_addresses_are_bracketed(self):
        self.assertEqual(endpoint_plan("::", 80), {
            "bind": ("::", 80),
            "advertised": "http://[::1]:80",
        })
        self.assertEqual(endpoint_plan("2001:db8::1", 65535), {
            "bind": ("2001:db8::1", 65535),
            "advertised": "http://[2001:db8::1]:65535",
        })
        self.assertEqual(endpoint_plan("0.0.0.0", 1234, "2001:db8::2"), {
            "bind": ("0.0.0.0", 1234),
            "advertised": "http://[2001:db8::2]:1234",
        })

    def test_explicit_wildcard_public_host_is_used_as_supplied(self):
        self.assertEqual(
            endpoint_plan("127.0.0.1", 99, "0.0.0.0")["advertised"],
            "http://0.0.0.0:99",
        )

    def test_port_boundaries(self):
        self.assertEqual(endpoint_plan("127.0.0.1", 1)["bind"], ("127.0.0.1", 1))
        self.assertEqual(endpoint_plan("127.0.0.1", 65535)["bind"], ("127.0.0.1", 65535))

    def test_invalid_arguments_raise_value_error(self):
        cases = [
            ("not-an-ip", 80, None),
            (None, 80, None),
            ("127.0.0.1", 80, "example.com"),
            ("127.0.0.1", 0, None),
            ("127.0.0.1", 65536, None),
            ("127.0.0.1", True, None),
            ("127.0.0.1", 80.0, None),
        ]
        for bind_host, port, public_host in cases:
            with self.subTest(bind_host=bind_host, port=port, public_host=public_host):
                with self.assertRaises(ValueError):
                    endpoint_plan(bind_host, port, public_host)


if __name__ == "__main__":
    unittest.main()

